import java.io.*;

public class Main {
    static List<String> ar = new ArrayList<>();
    static int solved = 0;

    static void moveStatues(List<int[]> v) {
        for (int i = 0; i < v.size(); i++) {
            v.get(i)[0]++;
        }
    }

    static int checkOnStatue(int i, int j, List<int[]> v) {
        for (int k = 0; k < v.size(); k++) {
            if (i == v.get(k)[0] && j == v.get(k)[1]) {
                return 1;
            }
        }
        return 0;
    }

    static int dfs(int i, int j, List<int[]> vIn, int[][] usedIn) {
        List<int[]> v = new ArrayList<>();
        for (int[] p : vIn) {
            v.add(new int[]{p[0], p[1]});
        }
        int[][] used = new int[8][8];
        for (int r = 0; r < 8; r++) {
            used[r] = usedIn[r].clone();
        }

        if (i < 0 || j < 0 || j >= 8 || i >= 8 || used[i][j] == 1) {
            return 0;
        }
        if (checkOnStatue(i, j, v) == 1) {
            return 0;
        }
        if (i == 0 && j == 7) {
            solved = 1;
            return 1;
        }
        moveStatues(v);
        if (checkOnStatue(i, j, v) == 1) {
            return 0;
        }
        int x = 0;
        used[i][j] = 1;

        x = Math.max(dfs(i - 1, j, v, used), x); if (solved == 1) return 1;
        x = Math.max(dfs(i, j + 1, v, used), x); if (solved == 1) return 1;
        x = Math.max(dfs(i, j - 1, v, used), x); if (solved == 1) return 1;
        x = Math.max(dfs(i + 1, j, v, used), x); if (solved == 1) return 1;
        x = Math.max(dfs(i + 1, j + 1, v, used), x); if (solved == 1) return 1;
        x = Math.max(dfs(i + 1, j - 1, v, used), x); if (solved == 1) return 1;
        x = Math.max(dfs(i - 1, j + 1, v, used), x); if (solved == 1) return 1;
        x = Math.max(dfs(i - 1, j - 1, v, used), x); if (solved == 1) return 1;
        x = Math.max(dfs(i, j, v, used), x); if (solved == 1) return 1;
        return x;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int[][] used = new int[8][8];

        List<int[]> v = new ArrayList<>();
        for (int i = 0; i < 8; i++) {
            String str = br.readLine().trim();
            ar.add(str);
            for (int j = 0; j < 8; j++) {
                if (str.charAt(j) == 'S') {
                    v.add(new int[]{i, j});
                }
            }
        }

        int x;
        x = dfs(7, 0, v, used);
        if (x == 1) {
            System.out.println("WIN");
            return;
        }
        x = dfs(6, 0, v, used);
        if (x == 1) {
            System.out.println("WIN");
            return;
        }
        x = dfs(6, 1, v, used);
        if (x == 1) {
            System.out.println("WIN");
            return;
        }
        x = dfs(7, 1, v, used);
        if (x == 1) {
            System.out.println("WIN");
            return;
        } else {
            System.out.println("LOSE");
        }
    }
}
